import app from "@/store/app";
import { Button, Tooltip } from "@arco-design/web-react";
import { IconSync } from "@arco-design/web-react/icon";
import React, { useMemo, useRef } from "react";
import { FormGenerateContext } from "react-converter-code";
import pageStore from "@/store/page";


const getSchema = (): JSONSchemaCustom => ({
	"type": "object",
    "title": "菜单",
	"properties": {
		// "id": {
		// 	"type": "number",
		// 	"title": "菜单 ID",
		// 	"default": null
		// },
		"parentId": {
			"type": "string",
			"title": "上级菜单",
			"colProps": {
				"span": 24
			},
			"format": "treeSelector",
			"fieldProps": {
				"type": "menu"	
			},
			"default": null,
		},
		"type": {
			"type": "string",
			"title": "菜单类型",
            "colProps": {
                "span": 24,
            },
			"format": "radio",
			"enum": [
				{ "label": "布局", "value": "layout" },
				{ "label": "目录", "value": "directory" },
                { "label": "菜单", "value": "menu" },
                // { "label": "外链", "value": "href" },
			],
			columnProps: {
				width: 90
			},
			"default": "menu"
		},
		"icon": {
			"type": "string",
			"title": "菜单图标",
			"format": "icon",
			"fieldProps": {
				type: "string",
			},
			"colProps": {
				"span": 24
			},
			columnProps: {
				width: 90
			},
			"default": null
		},
		"name": {
			"type": "string",
			"title": "菜单名称",
			"maxLength": 50,
			"default": null
		},
		"sort": {
			"type": "integer",
			"title": "排序",
			columnProps: {
				width: 70
			},
			"formItemProps":{
				"title": '显示排序'
			},
			"default": 10
		},
		"path": {
			"type": "string",
			"title": "路由地址",
			"show": {
                "type{}": ["menu", "directory", "layout"]
            },
			"maxLength": 100,
            "formItemProps": {
				tooltip: (
					<div>
						<p>/ 和 * 路由，排序设置要为路由最后面，否则其他路由会被覆盖无法生效</p>
					</div>
				),
				validator: (formData: any, callback) => {
					if(formData.path == '/' || formData.path == '*'){
						return;
					}
					if(formData.type == "menu"){
						if(formData.path.indexOf('/') == 0){
							callback("菜单路由不能以‘/’开头")
						}
					}else if(formData.type == "layout"){
						if(formData.path.indexOf('/') != 0){
							callback("布局路由请以‘/’开头")
						}
					}
					if(formData.path.endsWith('/')){
						if(!(formData.type == "layout" && formData.path == "/")){
							callback("菜单路由地址不能以‘/’结尾")
						}
					}

				},
                rules: [
                    {
                        required: true,
                        message: "路由地址不能为空",
                    }, {
                        match: /^[A-Za-z0-9\-\*\/]*$/g,
                        message: "地址只能输入英文、数字、-、/符号"
                    }
                ]
            },
			"default": null
		},
		// "mode": {
		// 	"type": "string",
		// 	"title": "菜单类型",
		// 	"show": {
		// 		"type": "menu"
		// 	},
		// 	"format": "radio",
		// 	"enum": [
		// 		{ "label": "原生", "value": "native", color: "green"  },
		// 		{ "label": "自定义", "value": "custom",  color: "arcoblue" },
		// 	],
		// 	"default": "native"
		// },
		"pageId": {
			"type": "number",
			"title": "关联页面",
			"format": "treeSelector",
            "show": {
                "type{}": ["menu", "layout"]
            },
            "fieldProps": {
                "type": "page",
				"treeCheckStrictly": true,
            },
			"default": null
		},
		"fileName": {
			"title": "关联页面"
		},
        "href": {
            "type": "string",
            "title": "外链地址",
			"format": "text",
            "show": {
                "type": "href",
            },
			"colProps": {
				span: 24
			}
        },
		// "userId": {
		// 	"type": "string",
		// 	"title": "创建用户",
		// 	"default": null
		// },
		// "authority": {
		// 	"type": "string",
		// 	"title": "权限字符",
		// 	"maxLength": 50,
		// 	"default": null
		// },
		// "isShow": {
		// 	"type": "boolean",
		// 	"title": "是否显示",
		// 	"format": "radio",
		// 	columnProps: {
		// 		width: 90
		// 	},
		// 	"enum": [
		// 		{ "value": 1, "label": "显示", "color": "blue" },
		// 		{ "value": 0, "label": "隐藏", "color": "red" }
		// 	],
		// 	"formItemProps": {
		// 		"tooltip": "关闭则路由将不会出现在侧边栏，但仍然可以访问",
		// 	},
		// 	"default": 1
		// },
		"isActive": {
			"type": "boolean",
			"title": "菜单状态",
			columnProps: {
				width: 90
			},
			"format": "radio",
			"enum": [
				{ "value": 1, "label": "正常", "color": "blue" },
				{ "value": 0, "label": "关闭", "color": "red" },
			],
			"formItemProps": {
				"tooltip": "关闭则路由将不会出现在侧边栏，也不能被访问",
			},
			"default": 1
		},
		// "description": {
		// 	"type": "string",
		// 	"title": "菜单描述",
		// 	"maxLength": 100,
		// 	"default": null
		// },
		"updatedAt": {
			"type": "string",
			"format": "dateTime",
			"title": "最近一次更新时间",
            "columnProps": {
                "width": 180,
            },
			"default": null
		}
	},
	"required": ['name', 'sort', 'path', 'href']
})

const Index = () => {

    const schema = useMemo(() => {
        return getSchema();
    },[])

    const ref = useRef<any>();

	const contextValue = useMemo<any>(() => {
		return { formats: getFormats() }
	},[])


    return (
		<FormGenerateContext.Provider value={contextValue}>
			<SchemaApiJsonPage
				ref={ref}
				notPagination
				apijson={{
					tableName: "Menu",
					uniqueKey: "id",
					logging: false,
					findParams: {
						"@order": "sort+",
					},
					processTableData: (data) => {
						console.log('data', data)
						return data;
					}
				}}
				onDataUpdate={() => {
					pageStore.getMenuList();
				}}
				joins={[
					{
						tableName: "Page",
						uniqueKey: "id",
						type: "One",
						foreignKey: "id",
						relationKey: "pageId",
						columns: ["title:fileName"]
					}
				]}
				treeBool
				queryFilterKeys={[]}
				formFilterKeys={['parentId', 'type', 'icon', 'name', 'sort', 'path', 'href', 'pageId', 'componentPath', 'isShow', 'isActive']}
				tableFilterKeys={['name', 'icon', 'type', 'sort', 'path', 'fileName', 'isShow',  'isActive', 'updatedAt']}
				logProps={{}}
				getToolBarRender={({ add }) => {
					return [
						<Tooltip key="reload" content="刷新列表">
							<Button size="small" icon={<IconSync />}
								onClick={() => {
									if(ref.current){
										ref.current.reload();
									}
								}}
							/>
						</Tooltip>,
						<Button size="small" type="primary" key="add" onClick={() => add()}>
							新增
						</Button>
					]
				}}
				getOperationList={(list, rowData) => {{


					return list.map((o) => {
						if(o.key == "add"){
							return {
								...o,
								hidden: rowData.type == "menu",
							}
						}
						return o;
					})
				}}}
				schemaTable={{
					headerTitle: "路由菜单管理",
				}}
				schema={schema}
			/>
		</FormGenerateContext.Provider>
    )
}

export default Index;